}

Method.Source:
/// <summary>
///     AVA <c>modified</c> method.
///     AVA - Schneider 07.03.2024
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean                     retVal;

    NDXLogisticsLocationName1   locNDXLogisticsLocationName1;
    FormDataSource              locFormDataSource;
    LogisticsPostalAddress      locLogisticsPostalAddress;

    retVal  = next modified();

    if(element.Args().menuItemName() == menuItemDisplayStr(smmBusRelQuickCreate))
    {
        locNDXLogisticsLocationName1                        = this.valueStr();

        locFormDataSource                                   = element.LogisticsPostalAddress_DS;
        locLogisticsPostalAddress                           = locFormDataSource.cursor();
        locLogisticsPostalAddress.NDXLogisticsLocationName1 = locNDXLogisticsLocationName1;
    }
    return retVal;
}
